import React, { useState, useRef, useContext } from 'react';
import { QrReader } from 'react-qr-reader';
import api from '../services/api';
import BackButton from '../components/BackButton';
import jsQR from 'jsqr';
import { SidebarContext } from '../context/AuthContext';

const AttendanceScanner = () => {
    const [result, setResult] = useState('');
    const [status, setStatus] = useState('idle'); // idle, processing, success, error
    const [message, setMessage] = useState('');
    const fileInputRef = useRef(null);
    const { setSidebarOpen } = useContext(SidebarContext);

    const processQR = async (data) => {
        if (!!data && status === 'idle') {
            try {
                setStatus('processing');
                const qrData = JSON.parse(data?.text || data);

                if (qrData.type !== 'attendance_qr' || !qrData.id) {
                    throw new Error('Invalid QR Code');
                }

                setMessage('Processing...');
                const response = await api.post('/attendance/qr-checkin', { user_id: qrData.id });

                setStatus('success');
                setResult(response.data.message);
                setMessage(response.data.message);

                // Reset after 3 seconds to allow next scan
                setTimeout(() => {
                    setStatus('idle');
                    setResult('');
                    setMessage('');
                }, 3000);

            } catch (err) {
                console.error(err);
                setStatus('error');
                setMessage(err.response?.data?.message || err.message || 'Scan Failed');

                setTimeout(() => {
                    setStatus('idle');
                    setMessage('');
                }, 3000);
            }
        }
    };

    const handleScan = (data, error) => {
        if (data) processQR(data);
        if (!!error) console.info(error);
    };

    const handleFileUpload = (e) => {
        const file = e.target.files[0];
        if (!file) return;

        const reader = new FileReader();
        reader.onload = (event) => {
            const img = new Image();
            img.onload = () => {
                const canvas = document.createElement('canvas');
                const context = canvas.getContext('2d');
                canvas.width = img.width;
                canvas.height = img.height;
                context.drawImage(img, 0, 0);
                const imageData = context.getImageData(0, 0, canvas.width, canvas.height);
                const code = jsQR(imageData.data, imageData.width, imageData.height);

                if (code) {
                    processQR(code.data);
                } else {
                    setStatus('error');
                    setMessage('No QR code found in image');
                    setTimeout(() => {
                        setStatus('idle');
                        setMessage('');
                    }, 3000);
                }
            };
            img.src = event.target.result;
        };
        reader.readAsDataURL(file);
        // Reset input so same file can be selected again
        e.target.value = '';
    };

    return (
        <div className="min-h-screen bg-gray-50 p-6 flex flex-col items-center">
            <div className="w-full max-w-xs">
                <BackButton />

                <div className="bg-white rounded-2xl shadow-xl overflow-hidden mt-4">
                    <div className="p-6 bg-indigo-600 text-white text-center">
                        <h1 className="text-xl font-bold">Scanner</h1>
                        <p className="opacity-80 text-xs mt-1">Scan QR to check in/out</p>
                    </div>

                    <div className="relative">
                        <div className="relative rounded-xl overflow-hidden shadow-2xl bg-black">
                            <QrReader
                                onResult={handleScan}
                                constraints={{ facingMode: 'environment' }}
                                scanDelay={500}
                                containerStyle={{ width: '100%', paddingTop: '100%' }} // Square (1:1) to fit max-w-xs
                                videoStyle={{ objectFit: 'cover', width: '100%', height: '100%' }}
                            />

                            {/* Visual Viewfinder Overlay */}
                            <div className="absolute inset-0 pointer-events-none flex items-center justify-center">
                                <div className="w-48 h-48 border-2 border-indigo-400/50 rounded-lg relative">
                                    {/* Corners */}
                                    {/* Corners */}
                                    <div className="absolute top-0 left-0 w-6 h-6 border-t-4 border-l-4 border-indigo-500 -mt-1 -ml-1"></div>
                                    <div className="absolute top-0 right-0 w-6 h-6 border-t-4 border-r-4 border-indigo-500 -mt-1 -mr-1"></div>
                                    <div className="absolute bottom-0 left-0 w-6 h-6 border-b-4 border-l-4 border-indigo-500 -mb-1 -ml-1"></div>
                                    <div className="absolute bottom-0 right-0 w-6 h-6 border-b-4 border-r-4 border-indigo-500 -mb-1 -mr-1"></div>
                                    {/* Scanning Line Animation */}
                                    <div className="absolute inset-x-0 h-0.5 bg-indigo-500/50 top-0 animate-[scan_2s_ease-in-out_infinite]"></div>
                                </div>
                            </div>
                        </div>

                        {/* Overlay for status */}
                        {status !== 'idle' && (
                            <div className={`absolute inset-0 flex items-center justify-center bg-black bg-opacity-80 transition-opacity duration-300 z-10`}>
                                <div className="text-center p-6">
                                    <div className={`text-5xl mb-4 ${status === 'success' ? 'text-green-500' : status === 'error' ? 'text-red-500' : 'text-blue-500 animate-pulse'}`}>
                                        {status === 'success' ? '✓' : status === 'error' ? '✕' : '...'}
                                    </div>
                                    <p className="text-white text-lg font-semibold">{message}</p>
                                </div>
                            </div>
                        )}
                    </div>

                    <div className="p-6 text-center space-y-4">
                        <p className="text-gray-500 text-sm">
                            Keep the QR code steady within the frame.
                        </p>

                        <div className="relative">
                            <div className="absolute inset-0 flex items-center">
                                <div className="w-full border-t border-gray-200"></div>
                            </div>
                            <div className="relative flex justify-center text-sm">
                                <span className="px-2 bg-white text-gray-500">Or scan from gallery</span>
                            </div>
                        </div>

                        <input
                            type="file"
                            accept="image/*"
                            className="hidden"
                            ref={fileInputRef}
                            onChange={handleFileUpload}
                        />
                        <button
                            onClick={() => fileInputRef.current.click()}
                            className="w-full flex items-center justify-center gap-2 bg-white border border-gray-300 hover:bg-gray-50 text-gray-700 px-4 py-2 rounded-lg font-medium transition-colors shadow-sm"
                        >
                            <svg className="w-5 h-5 text-gray-500" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16l4.586-4.586a2 2 0 012.828 0L16 16m-2-2l1.586-1.586a2 2 0 012.828 0L20 14m-6-6h.01M6 20h12a2 2 0 002-2V6a2 2 0 00-2-2H6a2 2 0 00-2 2v12a2 2 0 002 2z" />
                            </svg>
                            Upload QR Image
                        </button>

                        {status === 'success' && (
                            <div className="mt-4 p-3 bg-green-50 text-green-700 rounded-lg text-sm font-medium animate-pulse">
                                Last scan successful
                            </div>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
};

export default AttendanceScanner;
